            rst_flag[FB->i] = (uint8_t *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + RST_FLAG]);
            angle_ratio[FB->i] = (float *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + ANGLE_RATIO]);
            pulse_ratio[FB->i] = (float *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + PULSE_RATIO]);
