            torque_last_read_pos[FB->i] = (double *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + TORQUE_LAST_READ_POS]);
            torque_last_velocity[FB->i] = (float *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + TORQUE_LAST_VELOCITY]);
            now_motion_aimpos[FB->i] = (double *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + NOW_MOTION_AIMPOS]);
            phasing_target_position[FB->i] = (double *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + PHASING_TARGET_POSITION]);
